/**
 * 💡 THOUGHT PROCESS:
 * A detached, rounded, elevated SOLID bar -- not `NavigationBar`, which is edge-attached with no
 * margin or radius. The 2dp elevation is a deliberate, flagged exception to this codebase's
 * otherwise flat, no-shadow visual language (`nav_elevation` in dimens.xml, called out in
 * `CLAUDE.md`). No blur -- minSdk 26 has no `RenderEffect` to build one from, so a solid
 * background is not just a stylistic choice, it is the only option available without dropping
 * older devices.
 *
 * Fully rounded (stadium/pill) ends rather than the softer card-style rounding used elsewhere in
 * this app -- reuses `corner_radius_pill` (50dp), an existing dimen already used for pill chips. A
 * radius that large relative to the bar's own height doesn't overflow: Compose's rounded-rect
 * drawing caps each corner at half the shape's shortest side once the requested radius exceeds
 * that, so the same 50dp value produces a true stadium shape at whatever height this bar ends up
 * being, without needing to measure it. A thin `outline`-colored border traces the edge -- the same
 * token every card's hairline already uses -- so the bar reads as a clearly defined shape even when
 * the 2dp elevation shadow alone is too subtle to separate it from a similarly-toned background.
 *
 * Horizontal margin and the padding above the system nav bar both reuse `padding_standard` (12dp),
 * for the same reuse-over-invent reason.
 *
 * Takes `items: List<BottomNavItem>` rather than owning route/label definitions itself -- those
 * stay owned by the navigation layer (`PulseNavGraph.kt`), this composable is rendering-only.
 */
@Composable
fun FloatingBottomNav(
    items: List<BottomNavItem>,
    currentRoute: String?,
    onItemClick: (String) -> Unit,
    modifier: Modifier = Modifier
) {
    val cornerRadius = dimensionResource(id = R.dimen.corner_radius_pill)
    val elevation = dimensionResource(id = R.dimen.nav_elevation)
    // 💡 Both started at `padding_standard` (12dp) -- horizontal margin bumped to `padding_large`
    // (16dp) for more breathing room from the screen edges, kept as its own value so it can change
    // independently of the bottom margin. Bottom margin (the gap above the system nav bar) went the
    // other way, down to `padding_small` (4dp) -- 12dp read as an oversized gap once seen against
    // the rest of the app's tighter spacing.
    val horizontalMargin = dimensionResource(id = R.dimen.padding_medium)
    val bottomMargin = 0.dp
    val borderWidth = dimensionResource(id = R.dimen.border_thin)

    Surface(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = horizontalMargin)
            .windowInsetsPadding(WindowInsets.navigationBars)
            .padding(bottom = bottomMargin),
        shape = RoundedCornerShape(cornerRadius),
        color = MaterialTheme.colorScheme.surfaceContainerHighest,
        border = BorderStroke(borderWidth, MaterialTheme.colorScheme.primary.copy(alpha = 0.3f)),
        shadowElevation = elevation
    ) {
        Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 10.dp)) {
            items.forEach { item ->
                val isSelected = currentRoute == item.route
                val iconSize by animateDpAsState(
                    targetValue = if (isSelected) 22.dp else 20.dp,
                    label = "FloatingBottomNavIconSize"
                )

                NavigationBarItem(
                    modifier = Modifier.weight(1f),
                    selected = isSelected,
                    onClick = { onItemClick(item.route) },
                    label = { Text(text = item.label, textAlign = TextAlign.Center, fontSize = 10.sp) },
                    icon = {
                        Icon(
                            painter = painterResource(id = if (isSelected) item.selectedIconRes else item.unselectedIconRes),
                            contentDescription = item.label,
                            modifier = Modifier.size(iconSize),
                        )
                    },
                    colors = floatingNavItemColors()
                )
            }
        }
    }
}

@Composable
private fun floatingNavItemColors(): NavigationBarItemColors {
    val accentPrimary = LocalPulseColors.current.accentPrimary
    val mutedColor = LocalPulseColors.current.onSurfaceMuted
    return NavigationBarItemDefaults.colors(
        indicatorColor = Color.Transparent,
        selectedIconColor = accentPrimary,
        selectedTextColor = accentPrimary,
        unselectedIconColor = mutedColor,
        unselectedTextColor = mutedColor
    )
}

